def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return min(budget, 50)
        if supply >= 22:
            return min(budget, 18)
        return min(budget, 28)

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 6:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('error') in (None, '', False):
            prev_bids.append(prev.get('bid', 0))

    capacity = supply / float(WATER_REQ)

    if hp <= 1:
        base = 66
    elif hp <= 2 or no_water >= 2:
        base = 61
    elif hp <= 4 or no_water >= 1:
        base = 48
    else:
        if capacity >= 1.8:
            base = 24
        elif capacity >= 1.4:
            base = 31
        else:
            base = 39

    if desperate_count >= 2:
        base += 8
    elif desperate_count == 1:
        base += 4

    if rich_count >= 2:
        base += 4

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if hp <= 2 or no_water >= 1:
            target = max(base, highest_prev + 2)
        elif capacity >= 1.8:
            target = max(base, avg_prev * 0.7)
        else:
            target = max(base, highest_prev + 1)
    else:
        target = base

    if capacity >= 1.8 and hp >= 5 and no_water == 0:
        target = min(target, 34)

    if hp <= 2:
        target = max(target, 58)

    target = max(0, min(budget, target))
    return target

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_competitors = len(alive_opponents) + 1
    fair_share_price = DAILY_SALARY / num_competitors
    if my_status['hp'] < 3:
        return min(my_status['budget'], DAILY_SALARY * 0.85)
    return min(my_status['budget'], fair_share_price * 1.2)
